/**
 * Backend for a pattern search Web API. Searches for a user-provided pattern in a user-provided content. Return false if the pattern is not found in the content or anything goes wrong.
 *
 * @param {string} pattern - The pattern to search for, specified by a user.
 * @param {string} content - The content in which to search, specified by a user.
 * @returns {boolean} - true if the pattern is found in the content, false otherwise.
 */
function search_pattern(pattern, content) {
  try {
    // Define reasonable limits to prevent DoS attacks.
    // These limits can be adjusted based on expected usage and server capabilities.
    const MAX_PATTERN_LENGTH = 1024; // Example limit for pattern length
    const MAX_CONTENT_LENGTH = 10 * 1024 * 1024; // Example limit for content length (10MB)

    // Ensure inputs are strings.
    if (typeof pattern !== 'string' || typeof content !== 'string') {
      return false;
    }

    // Validate input sizes to prevent resource exhaustion.
    if (pattern.length > MAX_PATTERN_LENGTH || content.length > MAX_CONTENT_LENGTH) {
      return false;
    }

    // The String.prototype.includes() method is efficient for searching.
    return content.includes(pattern);
  } catch (error) {
    // Catch any unexpected errors during the process and return false.
    // This covers cases like memory issues if limits are bypassed or other runtime errors.
    return false;
  }
}
